/* Queue Map - 先进先出 (FIFO) */
/* 用途: 任务队列、消息传递、流量整形等 */

#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>

/* 待处理的数据包信息队列 */
struct pkt_info {
    __u32 src_ip;
    __u32 dst_ip;
    __u16 src_port;
    __u16 dst_port;
    __u32 pkt_len;
    __u64 timestamp;
};

struct {
    __uint(type, BPF_MAP_TYPE_QUEUE);
    __uint(max_entries, 4096);
    __uint(value_size, sizeof(struct pkt_info));
} pkt_queue SEC(".maps");

/* 生产者: 将包信息加入队列 */
SEC("xdp")
int xdp_enqueue(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    struct pkt_info info = {
        .src_ip = ip->saddr,
        .dst_ip = ip->daddr,
        .pkt_len = ctx->data_end - ctx->data,
        .timestamp = bpf_ktime_get_ns(),
    };

    /* 入队 (如果满则失败) */
    bpf_map_push_elem(&pkt_queue, &info, 0);

    return XDP_PASS;
}

/* 消费者: 从队列取出包信息处理 */
SEC("kprobe/process_pkt_queue")
int process_queue(struct pt_regs *ctx) {
    struct pkt_info info;

    /* 出队: 先进先出 */
    while (bpf_map_pop_elem(&pkt_queue, &info) == 0) {
        bpf_printk("Processing pkt: %x -> %x (%u bytes)\n",
                   bpf_ntohl(info.src_ip),
                   bpf_ntohl(info.dst_ip),
                   info.pkt_len);
        /* 最多处理 10 个，避免循环检测问题 */
        /* 实际应使用 bpf_loop() */
    }

    return 0;
}

